package br.com.oficina.infrastructure;

import br.com.oficina.domain.*;
import com.fasterxml.jackson.annotation.JsonFormat;
import jakarta.validation.Valid; import jakarta.validation.constraints.*;
import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
import org.springframework.beans.factory.annotation.Value;
import java.math.BigDecimal; import java.time.*; import java.util.*;

@RestController @RequestMapping("/api")
public class ApiController {
 private final ClienteRepository clientes; private final VeiculoRepository veiculos; private final ServicoRepository servicos; private final PecaRepository pecas; private final OrdemServicoRepository ordens; private final String integrationToken;
 ApiController(ClienteRepository c,VeiculoRepository v,ServicoRepository s,PecaRepository p,OrdemServicoRepository o,@Value("${app.integration-token:local-integration-token}") String integrationToken){clientes=c;veiculos=v;servicos=s;pecas=p;ordens=o;this.integrationToken=integrationToken;}
 @PostMapping("/clientes") @ResponseStatus(HttpStatus.CREATED) Cliente criarCliente(@Valid @RequestBody ClienteReq r){return clientes.save(new Cliente(documento(r.documento()),r.nome(),r.telefone(),r.email()));}
 @GetMapping("/clientes") List<Cliente> listarClientes(){return clientes.findAll();}
 @PutMapping("/clientes/{id}") Cliente atualizarCliente(@PathVariable UUID id,@Valid @RequestBody ClienteReq r){Cliente c=clientes.findById(id).orElseThrow(()->naoEncontrado("Cliente"));c.atualizar(r.nome(),r.telefone(),r.email());return clientes.save(c);}
 @DeleteMapping("/clientes/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void excluirCliente(@PathVariable UUID id){clientes.deleteById(id);}
 @PostMapping("/veiculos") @ResponseStatus(HttpStatus.CREATED) Veiculo criarVeiculo(@Valid @RequestBody VeiculoReq r){Cliente c=clientes.findById(r.clienteId()).orElseThrow(()->naoEncontrado("Cliente"));return veiculos.save(new Veiculo(c,placa(r.placa()),r.marca(),r.modelo(),r.ano()));}
 @GetMapping("/veiculos") List<Veiculo> listarVeiculos(){return veiculos.findAll();}
 @PutMapping("/veiculos/{id}") Veiculo atualizarVeiculo(@PathVariable UUID id,@Valid @RequestBody VeiculoReq r){Veiculo v=veiculos.findById(id).orElseThrow(()->naoEncontrado("Veículo"));v.atualizar(r.marca(),r.modelo(),r.ano());return veiculos.save(v);}
 @DeleteMapping("/veiculos/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void excluirVeiculo(@PathVariable UUID id){veiculos.deleteById(id);}
 @PostMapping("/servicos") @ResponseStatus(HttpStatus.CREATED) Servico criarServico(@Valid @RequestBody ServicoReq r){return servicos.save(new Servico(r.descricao(),r.preco(),r.minutosEstimados()));}
 @GetMapping("/servicos") List<Servico> listarServicos(){return servicos.findAll();}
 @PutMapping("/servicos/{id}") Servico atualizarServico(@PathVariable UUID id,@Valid @RequestBody ServicoReq r){Servico s=servicos.findById(id).orElseThrow(()->naoEncontrado("Serviço"));s.atualizar(r.descricao(),r.preco(),r.minutosEstimados());return servicos.save(s);}
 @DeleteMapping("/servicos/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void excluirServico(@PathVariable UUID id){servicos.deleteById(id);}
 @PostMapping("/pecas") @ResponseStatus(HttpStatus.CREATED) Peca criarPeca(@Valid @RequestBody PecaReq r){return pecas.save(new Peca(r.descricao(),r.precoUnitario(),r.estoque()));}
 @GetMapping("/pecas") List<Peca> listarPecas(){return pecas.findAll();}
 @PutMapping("/pecas/{id}") Peca atualizarPeca(@PathVariable UUID id,@Valid @RequestBody PecaReq r){Peca p=pecas.findById(id).orElseThrow(()->naoEncontrado("Peça"));p.atualizar(r.descricao(),r.precoUnitario(),r.estoque());return pecas.save(p);}
 @DeleteMapping("/pecas/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void excluirPeca(@PathVariable UUID id){pecas.deleteById(id);}
 @PostMapping("/ordens-servico") @ResponseStatus(HttpStatus.CREATED) @Transactional CriacaoOs criarOs(@Valid @RequestBody OsReq r){Cliente c=clientes.findByDocumento(documento(r.documento())).orElseThrow(()->naoEncontrado("Cliente"));Veiculo v=veiculos.findByPlaca(placa(r.placa())).filter(x->x.getCliente().getId().equals(c.getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Veículo não pertence ao cliente"));OrdemServico os=new OrdemServico(c,v);r.servicos().forEach(id->os.adicionarServico(servicos.findById(id).orElseThrow(()->naoEncontrado("Serviço"))));r.pecas().forEach((id,q)->{Peca p=pecas.findById(id).orElseThrow(()->naoEncontrado("Peça"));p.baixar(q);os.adicionarPeca(p,q);});OrdemServico salva=ordens.save(os);return new CriacaoOs(salva.getId(),salva.getStatus(),salva.getTotal(),salva.getCriadaEm());}
 @GetMapping("/ordens-servico") List<OrdemServico> listarOs(){return ordens.findAll().stream().filter(o->o.getStatus()!=StatusOs.FINALIZADA&&o.getStatus()!=StatusOs.ENTREGUE&&o.getStatus()!=StatusOs.ORCAMENTO_RECUSADO).sorted(Comparator.comparingInt((OrdemServico o)->prioridade(o.getStatus())).thenComparing(OrdemServico::getCriadaEm)).toList();}
 @GetMapping("/ordens-servico/{id}") OrdemServico detalharOs(@PathVariable UUID id){return ordens.findById(id).orElseThrow(()->naoEncontrado("OS"));}
 @PatchMapping("/ordens-servico/{id}/status") OrdemServico status(@PathVariable UUID id,@RequestBody StatusReq r){OrdemServico o=detalharOs(id);o.mudarStatus(r.status());return ordens.save(o);}
 @GetMapping("/ordens-servico/{id}/status") StatusResposta consultarStatus(@PathVariable UUID id){OrdemServico o=detalharOs(id);return new StatusResposta(o.getId(),o.getStatus(),o.getCriadaEm());}
 @PostMapping("/ordens-servico/{id}/enviar-orcamento") OrdemServico enviarOrcamento(@PathVariable UUID id){OrdemServico o=detalharOs(id);if(o.getStatus()==StatusOs.RECEBIDA)o.mudarStatus(StatusOs.EM_DIAGNOSTICO);o.mudarStatus(StatusOs.AGUARDANDO_APROVACAO);return ordens.save(o);}
 @PostMapping("/ordens-servico/{id}/aprovar") OrdemServico aprovar(@PathVariable UUID id){OrdemServico o=detalharOs(id);o.mudarStatus(StatusOs.EM_EXECUCAO);return ordens.save(o);}
 @PostMapping("/ordens-servico/{id}/orcamento/notificacao") OrdemServico notificarOrcamento(@PathVariable UUID id,@RequestHeader("X-Integration-Token") String token,@Valid @RequestBody OrcamentoNotificacao r){validarIntegracao(token);OrdemServico o=detalharOs(id);o.mudarStatus(r.aprovado()?StatusOs.EM_EXECUCAO:StatusOs.ORCAMENTO_RECUSADO);return ordens.save(o);}
 @PostMapping("/integracoes/email/status") OrdemServico receberStatusPorEmail(@RequestHeader("X-Integration-Token") String token,@Valid @RequestBody EmailStatus r){validarIntegracao(token);OrdemServico o=detalharOs(r.osId());o.mudarStatus(r.status());return ordens.save(o);}
 @GetMapping("/public/ordens-servico/{id}") Progresso progresso(@PathVariable UUID id,@RequestParam String documento){OrdemServico o=detalharOs(id);if(!o.getCliente().getDocumento().equals(documento(documento)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return new Progresso(o.getId(),o.getStatus(),o.getTotal(),o.getCriadaEm());}
 @GetMapping("/metricas/tempo-medio") Map<String,Long> tempoMedio(){return Map.of("minutos",ordens.findAll().stream().filter(o->o.getIniciadaEm()!=null&&o.getFinalizadaEm()!=null).mapToLong(o->Duration.between(o.getIniciadaEm(),o.getFinalizadaEm()).toMinutes()).average().stream().mapToLong(x->Math.round(x)).findFirst().orElse(0));}
 private void validarIntegracao(String token){if(!integrationToken.equals(token))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Token de integração inválido");} private static int prioridade(StatusOs status){return switch(status){case EM_EXECUCAO->0;case AGUARDANDO_APROVACAO->1;case EM_DIAGNOSTICO->2;case RECEBIDA->3;default->4;};} static ResponseStatusException naoEncontrado(String s){return new ResponseStatusException(HttpStatus.NOT_FOUND,s+" não encontrado");} static String documento(String v){String d=v.replaceAll("\\D","");boolean valido=d.length()==11?cpfValido(d):d.length()==14&&cnpjValido(d);if(!valido)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"CPF/CNPJ inválido");return d;} static boolean cpfValido(String d){if(d.chars().distinct().count()==1)return false;return digito(d,9,new int[]{10,9,8,7,6,5,4,3,2})==d.charAt(9)-'0'&&digito(d,10,new int[]{11,10,9,8,7,6,5,4,3,2})==d.charAt(10)-'0';} static boolean cnpjValido(String d){if(d.chars().distinct().count()==1)return false;return digito(d,12,new int[]{5,4,3,2,9,8,7,6,5,4,3,2})==d.charAt(12)-'0'&&digito(d,13,new int[]{6,5,4,3,2,9,8,7,6,5,4,3,2})==d.charAt(13)-'0';} static int digito(String d,int tamanho,int[] pesos){int soma=0;for(int i=0;i<tamanho;i++)soma+=(d.charAt(i)-'0')*pesos[i];int resto=soma%11;return resto<2?0:11-resto;} static String placa(String v){String p=v.replaceAll("[^A-Za-z0-9]","").toUpperCase();if(!p.matches("[A-Z]{3}[0-9][A-Z0-9][0-9]{2}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Placa inválida");return p;}
 record ClienteReq(@NotBlank String documento,@NotBlank String nome,String telefone,@Email String email){} record VeiculoReq(@NotNull UUID clienteId,@NotBlank String placa,@NotBlank String marca,@NotBlank String modelo,@Min(1900) @Max(2100) int ano){} record ServicoReq(@NotBlank String descricao,@NotNull @DecimalMin("0.01") BigDecimal preco,@Min(1) int minutosEstimados){} record PecaReq(@NotBlank String descricao,@NotNull @DecimalMin("0.01") BigDecimal precoUnitario,@Min(0) int estoque){} record OsReq(@NotBlank String documento,@NotBlank String placa,@NotEmpty List<UUID> servicos,Map<UUID,@Min(1) Integer> pecas){} record StatusReq(@NotNull StatusOs status){} record OrcamentoNotificacao(boolean aprovado,@NotBlank String origem){} record EmailStatus(@NotNull UUID osId,@NotNull StatusOs status,@NotBlank String remetente){} record CriacaoOs(UUID id,StatusOs status,BigDecimal total,Instant criadaEm){} record StatusResposta(UUID id,StatusOs status,Instant criadaEm){} record Progresso(UUID id,StatusOs status,BigDecimal total,Instant criadaEm){}
}
